<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Mars Odyssey Orbiter - By The Numbers</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            background-color: #111;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            font-family: 'Arial', sans-serif;
        }

        .container {
            width: 1600px;
            height: 900px;
            background: linear-gradient(155deg, #442a3f 0%, #87363e 30%, #cd4233 65%, #db5036 100%);
            position: relative;
            color: white;
            box-sizing: border-box;
            overflow: hidden;
        }

        /* Header Area */
        .header {
            position: absolute;
            top: 45px;
            right: 55px;
            display: flex;
            align-items: center;
        }

        .nasa-text {
            font-size: 11px;
            text-align: right;
            margin-right: 15px;
            line-height: 1.2;
            font-weight: normal;
        }

        .nasa-logo-placeholder {
            width: 75px;
            height: 75px;
            border: 1.5px solid white;
            border-radius: 50%;
            display: flex;
            justify-content: center;
            align-items: center;
            font-size: 18px;
            font-weight: bold;
            position: relative;
        }

        .nasa-logo-placeholder::before {
            content: '';
            position: absolute;
            width: 80%;
            height: 30%;
            border-top: 1px solid white;
            border-radius: 50%;
            transform: rotate(-15deg);
            top: 25px;
        }

        /* Title Area */
        .title-section {
            position: absolute;
            top: 95px;
            width: 100%;
            text-align: center;
        }

        .main-title {
            font-family: 'Impact', 'Arial Narrow Bold', sans-serif;
            font-size: 78px;
            font-weight: normal;
            margin: 0;
            letter-spacing: 0.5px;
        }

        .subtitle {
            font-size: 34px;
            font-weight: 300;
            letter-spacing: 5px;
            margin-top: 2px;
        }

        /* Main Content Layout */
        .content-area {
            position: absolute;
            top: 250px;
            left: 65px;
            right: 65px;
            height: 550px;
            display: flex;
            justify-content: space-between;
        }

        .column {
            display: flex;
            flex-direction: column;
            justify-content: flex-start;
        }

        .col-left {
            width: 33%;
            padding-top: 10px;
        }

        .col-center {
            width: 34%;
            position: relative;
        }

        .col-right {
            width: 33%;
            padding-top: 30px;
        }

        /* Data Points Formatting */
        .data-block {
            padding: 22px 0;
            position: relative;
        }

        .divider {
            height: 1px;
            background-color: rgba(255, 255, 255, 0.3);
        }

        .col-left .divider { width: 90%; }

        .col-right .divider { width: 95%; margin-left: auto; }
        .col-right .data-block { text-align: right; display: flex; flex-direction: column; align-items: flex-end; }

        .data-row {
            display: flex;
            align-items: center;
        }

        .col-right .data-row { justify-content: flex-end; width: 100%; }

        /* Typography */
        .number {
            font-family: 'Impact', 'Arial Narrow Bold', sans-serif;
            font-size: 110px;
            line-height: 0.85;
            font-weight: normal;
        }

        .col-left .number { margin-right: 18px; }

        .col-right .number { margin-left: 18px; }

        .text-main {
            font-size: 44px;
            line-height: 1.05;
            font-weight: 300;
        }

        .col-right .text-main { text-align: left; }

        .text-sub {
            font-size: 26px;
            font-weight: 300;
            margin-top: 10px;
        }

        /* Specific Element Adjustments */
        .orbits-row {
            align-items: flex-end;
            padding-bottom: 5px;
        }
        .orbits-num {
            font-size: 100px;
            letter-spacing: 1px;
        }
        .orbits-text {
            font-size: 40px;
            padding-bottom: 5px;
        }

        .relay-row {
            align-items: center;
            margin-bottom: 5px;
        }
        .relay-text-left {
            text-align: right;
            font-size: 38px;
            line-height: 1.1;
            font-weight: 300;
            margin-right: 15px;
        }
        .relay-num {
            font-size: 110px;
            margin-left: 0;
        }
        .relay-text-bottom {
            font-size: 38px;
            font-weight: 300;
            text-align: right;
        }

        /* Center Image Placeholder */
        .satellite-placeholder {
            position: absolute;
            top: -20px;
            left: 50%;
            transform: translateX(-50%) rotate(15deg);
            width: 380px;
            height: 550px;
            border: 2px dashed rgba(255,255,255,0.4);
            background: rgba(0,0,0,0.15);
            display: flex;
            justify-content: center;
            align-items: center;
            text-align: center;
            font-style: italic;
            font-size: 18px;
            padding: 20px;
            box-sizing: border-box;
        }

        /* Footer */
        .footer {
            position: absolute;
            bottom: 45px;
            left: 65px;
            right: 65px;
            display: flex;
            justify-content: space-between;
            font-size: 20px;
            font-weight: 300;
            letter-spacing: 0.5px;
        }
    </style>
</head>
<body>
