                    </div>
                </div>

                <div class="divider"></div>

                <div class="data-block">
                    <div class="data-row">
                        <div class="number" style="letter-spacing: -1px;">1.33</div>
                        <div class="text-main">Terabits of<br>Data Relayed</div>
                    </div>
                    <div class="text-sub">from Mars Surface Missions</div>
                </div>
            </div>

            <!-- Center Column Placeholder -->
            <div class="column col-center">
                <div class="satellite-placeholder placeholder">
                    [3D Render of Mars Odyssey Orbiter spacecraft, angled with solar panels deployed against gradient background]
                </div>
            </div>

            <!-- Right Column -->
            <div class="column col-right">
                <div class="data-block" style="padding-top: 0px;">
                    <div class="data-row orbits-row">
                        <div class="number orbits-num">100,000</div>
