                    </div>
                </div>

                <div class="divider"></div>

                <div class="data-block">
                    <div class="data-row relay-row">
                        <div class="relay-text-left">Relay Support<br>for</div>
                        <div class="number relay-num">6</div>
                    </div>
                    <div class="relay-text-bottom">Mars Missions</div>
                </div>
            </div>

        </div>

        <!-- Bottom Footer -->
        <div class="footer">
            <div>science.nasa.gov/mission/odyssey</div>
            <div>Updated June 2024</div>
        </div>

    </div>
</body>
</html>
